fn deliver_plain_opt_string(value: Option<String>, out: *mut *mut c_char) -> MarmotStatus {
    let ptr = crate::memory::owned_opt_c_string(value);
    match unsafe { write_out(out, ptr) } {
        Ok(()) => MarmotStatus::Ok,
        Err(status) => {
            unsafe { crate::memory::free_c_string(ptr) };
            status
        }
    }
}

