/// Copy a borrowed `(ptr, len)` byte buffer. `(NULL, 0)` is empty; NULL
/// with a nonzero length is an error.
unsafe fn byte_array(ptr: *const u8, len: usize) -> Result<Vec<u8>, MarmotStatus> {
    if ptr.is_null() {
        if len == 0 {
            return Ok(Vec::new());
        }
        crate::status::set_last_error("byte buffer was NULL with nonzero length");
        return Err(MarmotStatus::NullPointer);
    }
    Ok(unsafe { std::slice::from_raw_parts(ptr, len) }.to_vec())
}

/// Borrow-check a required input-struct pointer.
unsafe fn borrowed<'a, T>(ptr: *const T) -> Result<&'a T, MarmotStatus> {
    if ptr.is_null() {
        crate::status::set_last_error("required struct argument was NULL");
        return Err(MarmotStatus::NullPointer);
    }
    Ok(unsafe { &*ptr })
}

/// Read a borrowed `(ptr, len)` array of input structs through a per-item
/// `to_ffi` conversion. `(NULL, 0)` is empty; NULL with nonzero length is
/// an error.
unsafe fn struct_array<T, F, R>(
    ptr: *const T,
    len: usize,
    convert: F,
) -> Result<Vec<R>, MarmotStatus>
where
    F: Fn(&T) -> Result<R, MarmotStatus>,
{
    if ptr.is_null() {
        if len == 0 {
            return Ok(Vec::new());
        }
        crate::status::set_last_error("struct array was NULL with nonzero length");
        return Err(MarmotStatus::NullPointer);
    }
    let mut out = Vec::with_capacity(len);
    for i in 0..len {
        out.push(convert(unsafe { &*ptr.add(i) })?);
    }
    Ok(out)
}
